function toUsage(raw: any): Usage | undefined {
  if (!raw) return undefined;
  return {
    promptTokens: raw.input_tokens,
    completionTokens: raw.output_tokens,
    totalTokens: (raw.input_tokens ?? 0) + (raw.output_tokens ?? 0),
  };
}

