src/concurrency.ts::Semaphore.source_code:
class Semaphore {
  private available: number;
  private readonly max: number;
  private readonly waiters: Waiter[] = [];

  constructor(max: number) {
    this.available = max;
    this.max = max;
  }

  /** Slots currently in use — for progress logging only, not for control flow. */
  get busy(): number {
    return this.max - this.available;
  }

  /** Requests currently queued waiting for a slot — for progress logging only. */
  get queued(): number {
    return this.waiters.length;
  }

  /**
   * Resolves with a release() function once a slot is free. If `signal`
   * fires while still queued (client disconnected, or a timeout that spans
   * the wait), the wait is abandoned and the promise rejects with
   * AbortedWhileQueuedError — no slot is ever taken for it.
   *
   * release() is safe to call more than once; only the first call has an
   * effect.
   */
  acquire(signal?: AbortSignal): Promise<() => void> {
    return new Promise((resolve, reject) => {
      let released = false;
      const release = () => {
        if (released) return;
        released = true;
        this.available++;
        this.dequeueNext();
      };

      const grant = () => {
        this.available--;
        resolve(release);
      };

      if (this.available > 0) {
        grant();
        return;
      }

      if (signal?.aborted) {
        reject(new AbortedWhileQueuedError());
        return;
      }

      const waiter: Waiter = { grant };
      if (signal) {
        const onAbort = () => {
          const idx = this.waiters.indexOf(waiter);
          if (idx !== -1) this.waiters.splice(idx, 1);
          reject(new AbortedWhileQueuedError());
        };
        waiter.signal = signal;
        waiter.onAbort = onAbort;
        signal.addEventListener("abort", onAbort, { once: true });
      }
      this.waiters.push(waiter);
    });
  }

  private dequeueNext(): void {
    const waiter = this.waiters.shift();
    if (!waiter) return;
    if (waiter.signal && waiter.onAbort) {
      waiter.signal.removeEventListener("abort", waiter.onAbort);
    }
    waiter.grant();
  }
}

