src/openai.ts::flattenMessages.source_code:
function flattenMessages(messages: ChatMessage[]): { system?: string; prompt: string } {
  const systemParts: string[] = [];
  const turns: string[] = [];

  for (const m of messages) {
    if (m.role === "system") {
      systemParts.push(m.content);
    } else if (m.role === "user") {
      turns.push(`Human: ${m.content}`);
    } else if (m.role === "assistant") {
      turns.push(`Assistant: ${m.content}`);
    }
  }

  return {
    system: systemParts.length > 0 ? systemParts.join("\n\n") : undefined,
    prompt: turns.join("\n\n"),
  };
}

src/openai.ts::checkMessages.source_code:
function checkMessages(messages: ChatMessage[]): string | undefined {
  const hasTurn = messages.some((m) => m.role === "user" || m.role === "assistant");
  return hasTurn ? undefined : `"messages" must include at least one "user" or "assistant" message`;
}

